function StatusPill({ children, tone = "neutral" }: { children: React.ReactNode; tone?: "neutral" | "warning" | "success" }) {
  const className = tone === "warning" ? "bg-admin-warning-soft text-admin-warning" : tone === "success" ? "bg-admin-green-soft text-admin-success" : "bg-admin-neutral-soft text-admin-muted";
  return <span className={["rounded-full px-3 py-1.5 text-[12px] font-bold", className].join(" ")}>{children}</span>;
}

function MetricCard({ title, value, note, tone = "blue" }: { title: string; value: string; note: string; tone?: "blue" | "green" | "orange" }) {
  const iconClass = tone === "green" ? "bg-admin-green-soft text-admin-success" : tone === "orange" ? "bg-admin-warning-soft text-admin-warning" : "bg-admin-blue-soft text-admin-blue";
  return <article className="admin-panel-shadow rounded-[8px] border border-admin-border bg-white px-5 py-5"><span className={["grid h-12 w-12 place-items-center rounded-[8px]", iconClass].join(" ")}><BotIcon className="h-6 w-6" /></span><p className="mt-6 text-[13px] font-bold uppercase text-admin-muted">{title}</p><div className="mt-3 flex items-center justify-between gap-3"><p className="text-[24px] font-bold text-admin-ink">{value}</p><p className="text-[12px] font-bold text-admin-muted">{note}</p></div></article>;
}

